create table if not exists public.tickets(ticket_id text primary key,guest_name text not null,ticket_number text not null unique,ticket_type text not null check(ticket_type in('guest','teacher')),ticket_role text not null,used boolean not null default false,checked_in_at timestamptz);
create table if not exists public.checkins(id bigint generated always as identity primary key,ticket_id text not null references public.tickets(ticket_id),guest_name text not null,ticket_number text not null,ticket_type text not null,ticket_role text not null,checked_in_at timestamptz not null default now());
alter table public.tickets enable row level security;alter table public.checkins enable row level security;
create policy "public can read checkins" on public.checkins for select to anon using(true);
alter publication supabase_realtime add table public.checkins;
create or replace function public.register_guest(p_ticket_id text,p_guest_name text,p_ticket_number text) returns jsonb language plpgsql security definer set search_path=public as $$ declare t public.tickets; begin if p_ticket_id not like 'PT-2026-O-%' or length(trim(p_guest_name))<2 then raise exception 'invalid ticket';end if;insert into public.tickets(ticket_id,guest_name,ticket_number,ticket_type,ticket_role) values(p_ticket_id,left(trim(p_guest_name),60),p_ticket_number,'guest','PREMIERE GUEST') on conflict(ticket_id) do nothing;select * into t from public.tickets where ticket_id=p_ticket_id;return jsonb_build_object('ticketId',t.ticket_id,'name',t.guest_name,'number',t.ticket_number,'type',t.ticket_type,'role',t.ticket_role);end $$;
revoke all on function public.register_guest(text,text,text) from public;grant execute on function public.register_guest(text,text,text) to anon;
create or replace function public.check_in_ticket(p_ticket_id text) returns jsonb language plpgsql security definer set search_path=public as $$ declare t public.tickets; begin select * into t from public.tickets where ticket_id=p_ticket_id for update;if not found then return jsonb_build_object('status','invalid','ticket_id',p_ticket_id);end if;if t.used then return jsonb_build_object('status','used','ticket_id',t.ticket_id,'name',t.guest_name,'number',t.ticket_number,'type',t.ticket_type,'role',t.ticket_role,'checked_in_at',t.checked_in_at);end if;update public.tickets set used=true,checked_in_at=now() where ticket_id=p_ticket_id returning * into t;insert into public.checkins(ticket_id,guest_name,ticket_number,ticket_type,ticket_role,checked_in_at)values(t.ticket_id,t.guest_name,t.ticket_number,t.ticket_type,t.ticket_role,t.checked_in_at);return jsonb_build_object('status','valid','ticket_id',t.ticket_id,'name',t.guest_name,'number',t.ticket_number,'type',t.ticket_type,'role',t.ticket_role,'checked_in_at',t.checked_in_at);end $$;
revoke all on function public.check_in_ticket(text) from public;grant execute on function public.check_in_ticket(text) to anon;
insert into public.tickets values('PT-2026-G027-A7K2','Марія Коваль','027','guest','SPECIAL GUEST',false,null),('PT-2026-G031-X9M4','Гліб Юхимук','031','guest','CREW GUEST',false,null),('PT-2026-G044-P3R8','Олександр Бондар','044','guest','PREMIERE GUEST',false,null),('PT-2026-G052-H6T1','Анна Мельник','052','guest','SPECIAL GUEST',false,null),('PT-2026-T001-V8Q5','Іван Петрович','T01','teacher','HONORED GUEST',false,null),('PT-2026-T002-C4N7','Олена Василівна','T02','teacher','HONORED GUEST',false,null) on conflict(ticket_id) do update set guest_name=excluded.guest_name,ticket_number=excluded.ticket_number,ticket_type=excluded.ticket_type,ticket_role=excluded.ticket_role;
